#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
source "${SCRIPT_DIR}/common.sh"

if ! tmux has-session -t "=${WATCHDOG_SESSION}" 2>/dev/null; then
  echo "Dashboard release watchdog: stopped" >&2
  exit 1
fi
if [[ ! -s "${WATCHDOG_STATUS_FILE}" ]]; then
  echo "Dashboard release watchdog: starting (no completed check yet)" >&2
  exit 1
fi

# The file is generated by watchdog-loop.sh with shell-escaped values only.
source "${WATCHDOG_STATUS_FILE}"
now_epoch="$(date +%s)"
if [[ ! "${checked_epoch:-}" =~ ^[0-9]+$ ]] || \
   (( now_epoch - checked_epoch > WATCHDOG_MAX_STATUS_AGE_SECONDS )); then
  echo "Dashboard release watchdog: stale status (last check ${checked_at:-unknown})" >&2
  exit 1
fi
if [[ "${result:-failed}" != "ok" ]]; then
  echo "Dashboard release watchdog: last check needs attention (${result:-failed}) at ${checked_at:-unknown}" >&2
  echo "Log: ${WATCHDOG_LOG_FILE}" >&2
  exit 1
fi
if [[ "${source_commit:-}" != "${deployed_commit:-}" || \
      "${source_commit:-}" != "${live_verified_commit:-}" ]]; then
  echo "Dashboard release watchdog: commit state is not converged" >&2
  echo "source=${source_commit:-missing} deployed=${deployed_commit:-missing} live=${live_verified_commit:-missing}" >&2
  exit 1
fi

echo "Dashboard release watchdog: healthy"
echo "Last check: ${checked_at}"
echo "Verified commit: ${source_commit}"
echo "Fixed URL: ${FIXED_PUBLIC_URL}"
